// ===========================================================================
// Session 14: structure files ported against the dump.
// ===========================================================================

#[test]
fn packet_flow_matches_the_jar() {
    // SERVERBOUND is ordinal 0, not 1 -- it is easy to assume the client-bound one leads.
    assert_enum(
        "net.minecraft.network.protocol.PacketFlow",
        &[("SERVERBOUND", 0), ("CLIENTBOUND", 1)],
    );
    assert_enum_field(
        "net.minecraft.network.protocol.PacketFlow",
        "SERVERBOUND",
        "id",
        "str:serverbound",
    );
    assert_enum_field(
        "net.minecraft.network.protocol.PacketFlow",
        "CLIENTBOUND",
        "id",
        "str:clientbound",
    );
}

#[test]
fn dialog_action_matches_the_jar() {
    assert_enum(
        "net.minecraft.server.dialog.DialogAction",
        &[("CLOSE", 0), ("NONE", 1), ("WAIT_FOR_RESPONSE", 2)],
    );
    // Both fields, on all three: `id` is the BY_ID key and `name` is the persisted spelling.
    for (c, id, name) in [
        ("CLOSE", 0, "close"),
        ("NONE", 1, "none"),
        ("WAIT_FOR_RESPONSE", 2, "wait_for_response"),
    ] {
        assert_enum_field("net.minecraft.server.dialog.DialogAction", c, "id", &format!("i32:{id}"));
        assert_enum_field(
            "net.minecraft.server.dialog.DialogAction",
            c,
            "name",
            &format!("str:{name}"),
        );
    }
}

#[test]
fn quart_pos_constants_match_the_jar() {
    for (f, v) in [("BITS", 2), ("SIZE", 4), ("MASK", 3)] {
        assert_const("net.minecraft.core.QuartPos", f, &format!("i32:{v}"));
    }
}

#[test]
fn quart_pos_shifts_match_the_jar_semantics() {
    use minecraft_rust::net::minecraft::core::QuartPos::QuartPos;

    // `fromBlock` and `quartLocal` DISAGREE about negatives, which is the whole reason both exist:
    // `-1 >> 2 == -1` but `-1 & 3 == 3`. A port that made either of them floor uniformly would
    // be self-consistent and wrong.
    assert_eq!(QuartPos::from_block(-1), -1, "fromBlock floors toward -inf");
    assert_eq!(QuartPos::quart_local(-1), 3, "quartLocal is always 0..=3");
    assert_eq!(QuartPos::from_block(7), 1);
    assert_eq!(QuartPos::quart_local(7), 3);

    // Round trips: `toBlock` inverts `fromBlock` only for the quart's own block, and
    // `toSection`/`fromSection` are exact inverses at every quart boundary.
    for q in [-9i32, -4, -1, 0, 1, 4, 9, 16] {
        assert_eq!(
            QuartPos::to_section(QuartPos::from_section(q)),
            q,
            "fromSection/toSection are exact inverses"
        );
    }
    assert_eq!(QuartPos::from_section(3), 12, "fromSection is a plain `<< 2`");
    assert_eq!(QuartPos::to_block(3), 12, "toBlock is a plain `<< 2`");
}